    27→/// GMP-based modular exponentiation implementation
    28→pub(crate) fn modexp(base: &[u8], exponent: &[u8], modulus: &[u8]) -> Vec<u8> {
    29→    use rug::{integer::Order::Msf, Integer};
    30→    // Convert byte slices to GMP integers
    31→    let base_int = Integer::from_digits(base, Msf);
    32→    let exp_int = Integer::from_digits(exponent, Msf);
    33→    let mod_int = Integer::from_digits(modulus, Msf);
    34→
    35→    // Perform modular exponentiation using GMP's pow_mod
    36→    let result = base_int.pow_mod(&exp_int, &mod_int).unwrap_or_default();
    37→
    38→    // Convert result back to bytes
    39→    let byte_count = result.significant_bits().div_ceil(8);
    40→    let mut output = vec![0u8; byte_count as usize];
    41→    result.write_digits(&mut output, Msf);
    42→    output
    43→}
