   174→/// Calculate the gas cost for the modexp precompile with BYZANTIUM gas rules.
   175→pub fn byzantium_gas_calc(base_len: u64, exp_len: u64, mod_len: u64, exp_highp: &U256) -> u64 {
   176→    gas_calc::<0, 8, 20, _>(base_len, exp_len, mod_len, exp_highp, |max_len| -> U256 {
   177→        // Output of this function is bounded by 2^128
   178→        if max_len <= 64 {
   179→            U256::from(max_len * max_len)
   180→        } else if max_len <= 1_024 {
   181→            U256::from(max_len * max_len / 4 + 96 * max_len - 3_072)
   182→        } else {
   183→            // Up-cast to avoid overflow
   184→            let x = U256::from(max_len);
   185→            let x_sq = x * x; // x < 2^64 => x*x < 2^128 < 2^256 (no overflow)
   186→            x_sq / U256::from(16) + U256::from(480) * x - U256::from(199_680)
   187→        }
   188→    })
   189→}
   190→
   191→/// Calculate gas cost according to EIP 2565:
   192→/// <https://eips.ethereum.org/EIPS/eip-2565>
   193→pub fn berlin_gas_calc(base_len: u64, exp_len: u64, mod_len: u64, exp_highp: &U256) -> u64 {
   194→    gas_calc::<200, 8, 3, _>(base_len, exp_len, mod_len, exp_highp, |max_len| -> U256 {
   195→        let words = U256::from(max_len.div_ceil(8));
   196→        words * words
   197→    })
   198→}
   199→
   200→/// Calculate gas cost according to EIP-7883:
   201→/// <https://eips.ethereum.org/EIPS/eip-7883>
   202→///
   203→/// There are three changes:
   204→/// 1. Increase minimal price from 200 to 500
   205→/// 2. Increase cost when exponent is larger than 32 bytes
   206→/// 3. Increase cost when base or modulus is larger than 32 bytes
   207→pub fn osaka_gas_calc(base_len: u64, exp_len: u64, mod_len: u64, exp_highp: &U256) -> u64 {
   208→    gas_calc::<500, 16, 1, _>(base_len, exp_len, mod_len, exp_highp, |max_len| -> U256 {
   209→        if max_len <= 32 {
   210→            return U256::from(16); // multiplication_complexity = 16
   211→        }
   212→
   213→        let words = U256::from(max_len.div_ceil(8));
