    13→/// Map the latest active hardfork at the given timestamp or block number to a revm [`SpecId`].
    14→pub fn revm_spec_by_timestamp_and_block_number<C>(
    15→    chain_spec: &C,
    16→    timestamp: u64,
    17→    block_number: u64,
    18→) -> SpecId
    19→where
    20→    C: EthereumHardforks,
    21→{
    22→    if chain_spec.is_osaka_active_at_timestamp(timestamp) {
    23→        SpecId::OSAKA
    24→    } else if chain_spec.is_prague_active_at_timestamp(timestamp) {
    25→        SpecId::PRAGUE
    26→    } else if chain_spec.is_cancun_active_at_timestamp(timestamp) {
    27→        SpecId::CANCUN
    28→    } else if chain_spec.is_shanghai_active_at_timestamp(timestamp) {
    29→        SpecId::SHANGHAI
    30→    } else if chain_spec.is_paris_active_at_block(block_number) {
    31→        SpecId::MERGE
    32→    } else if chain_spec.is_london_active_at_block(block_number) {
    33→        SpecId::LONDON
    34→    } else if chain_spec.is_berlin_active_at_block(block_number) {
    35→        SpecId::BERLIN
    36→    } else if chain_spec.is_istanbul_active_at_block(block_number) {
    37→        SpecId::ISTANBUL
    38→    } else if chain_spec.is_petersburg_active_at_block(block_number) {
